import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {World} from '../world.js';import {Battle,makeEnemy} from '../battle.js?v=5.6.0';import {defaultHero} from '../mako.js';import {combatContext} from '../combat-reactions.js';import {bellArcObjects,bellArcState,settleBellArc,bellArcObjective,bellBattleContext,validateBellArc} from '../bell-witness-arc.js';import {resonancePoints} from '../resonance-link.js';import {findPath} from '../navigation.js';import {dialoguePages} from '../dialogue-presentation.js';
const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url))),voices=JSON.parse(fs.readFileSync(new URL('../voices/manifest.json',import.meta.url))).lines;
function setup(){let dialog;const w=new World(data,{onDialog:d=>dialog=d});w.state.story.firstCore=true;w.state.story.parcel=true;w.state.chapter=4;w.state.scene=292;w.state.mode='field';return {w,get dialog(){return dialog;},use(o){w.state.x=o.xy[0]+.5;w.state.y=o.xy[1]+.5;w.state.mode='field';w.interact(o);},close(){const d=dialog;dialog=null;d?.after?.();}};}
function prepare(route=0){const t=setup(),w=t.w,choose=i=>{t.dialog.choices[i].action();t.close();},use=id=>{t.use(bellArcObjects(w).find(o=>o.bellArc===id));};t.use(w.scene.objects.find(o=>o.type==='npc'&&o.sprite===18));t.close();use('soot');t.close();use('inlet');choose(0);w.state.scene=125;t.use(w.scene.objects.find(o=>o.type==='npc'&&o.sprite===23));t.close();use('plate');t.close();use('sump');choose(0);w.state.scene=704;const bells=w.scene.objects.find(o=>o.investigationRole==='control');for(const choice of [0,2,1,0]){t.use(bells);choose(choice);}t.use(w.scene.objects.find(o=>o.exploreId==='district:4:keepsake'));t.close();w.state.scene=125;use('diverter');choose(0);use('diverter');choose(0);use('diverter');choose(1);use('diverter');choose(route);return t;}
test('clues and physical return sites occupy distinct reachable floor beside the existing voiced arc',()=>{const {w}=setup();let count=0;for(const id of [292,125]){w.state.scene=id;const used=new Set();for(const o of bellArcObjects(w)){assert.ok(!used.has(o.xy.join(',')));used.add(o.xy.join(','));assert.ok(w.scene.floor[o.xy[1]][o.xy[0]]==='.');assert.ok(findPath(w.scene,w.scene.arrive,o.xy,1).length||Math.hypot(o.xy[0]-w.scene.arrive[0],o.xy[1]-w.scene.arrive[1])<=1);count++;}}assert.equal(count,5);});
test('preparation requires evidence and both conversations; remote interaction and repeated clues cannot advance it',()=>{const t=setup(),w=t.w;w.state.scene=125;const o=bellArcObjects(w).find(o=>o.bellArc==='diverter');t.use(o);assert.equal(t.dialog.choices,undefined);t.close();const plate=bellArcObjects(w).find(o=>o.bellArc==='plate');w.state.x=-30;w.state.y=-30;w.interact(plate);assert.deepEqual(bellArcState(w.state).evidence,[]);t.use(plate);t.close();t.use(plate);t.close();assert.equal(bellArcState(w.state).evidence.length,1);assert.equal(bellArcState(w.state).preparation,null);});
test('two earned preparations have distinct actual battle effects without stacking or changing other bosses',()=>{for(const [choice,route]of [[0,'shelter'],[1,'lure']]){const {w}=prepare(choice);w.state.scene=292;assert.equal(bellArcState(w.state).preparation,route);const heroes=[defaultHero(0,4)],e=makeEnemy('boss',4,0,true);heroes[0].x=0;heroes[0].y=0;e.x=4;e.y=0;const context=combatContext(w),b=new Battle({heroes,enemies:[e],chapter:4,context});assert.equal(heroes[0].status.shield||0,choice===0?24:0);b.planEnemy(e);const first=e.intent.total;if(choice===1){assert.ok(e.bellLureSpent);b.planEnemy(e);assert.ok(Math.abs(first-e.intent.total-1.4)<1e-6);}const c=new Battle({heroes:[defaultHero(0,4)],enemies:[makeEnemy('boss',3,0,true)],chapter:3,context});assert.equal(c.heroes[0].status.shield,undefined);}});
test('bell completion relocates the witness once and keeps its authored aftermath and exact recorded conversation anchors',()=>{const {w}=prepare();assert.ok(w.objects().some(o=>o.type==='npc'&&o.sprite===23));w.setBit(8323556,1);assert.ok(!w.objects().some(o=>o.type==='npc'&&o.sprite===23));w.state.scene=292;const witness=w.objects().find(o=>o.bellArc==='witness');assert.ok(witness);assert.ok(!bellArcObjects(w).filter(o=>o.type==='switch').some(o=>o.xy.join(',')===witness.xy.join(',')));assert.equal(witness.text,w.scenes.get(125).objects.find(o=>o.sprite===23).after);const anchors=[w.scenes.get(125).objects.find(o=>o.sprite===23).text,w.scenes.get(292).objects.find(o=>o.sprite===18).text];for(const seg of dialoguePages(anchors).flatMap(p=>p.voiceSegments))assert.ok(voices.some(l=>l.speaker===seg.speaker&&l.text===seg.text),seg.text);});
test('aftermath earns one growth once only after victory and preserves evidence, preparation and spent charge across saves',()=>{const {w}=prepare();settleBellArc(w);assert.equal(resonancePoints(w.state),0);w.state.bosses.push(4);settleBellArc(w);settleBellArc(w);assert.equal(resonancePoints(w.state),1);assert.ok(w.state.story.journal.some(j=>j.id==='bell-aftermath'));const value=w.save();w.restore(value);assert.equal(w.state.bellWitness.preparation,'shelter');assert.equal(w.state.bellWitness.completed,true);settleBellArc(w);assert.equal(resonancePoints(w.state),1);const b=new Battle({heroes:[defaultHero(0,4)],enemies:[makeEnemy('boss',4,0,true)],chapter:4,context:{bellPreparation:'lure'}});b.planEnemy(b.enemies[0]);const copy=new Battle({heroes:[defaultHero(0,4)],enemies:[]});copy.restore(b.snapshot());assert.equal(copy.enemies[0].bellLureSpent,true);});
test('optional guidance names a real investigation target and does not intrude into other eras or chapters',()=>{const t=setup(),w=t.w;t.use(bellArcObjects(w).find(o=>o.bellArc==='soot'));t.close();assert.ok(bellArcObjective(w)?.object);w.state.chapter=5;assert.equal(bellArcObjective(w),null);w.state.chronicle={phase:'past'};assert.equal(bellArcObjects(w).length,0);});
test('physical repair earns the return-wave descriptor while a legacy preparation survives unchanged',()=>{const {w}=prepare(1);assert.deepEqual(bellBattleContext(w).bellCircuit,{version:1,mode:'lure',repaired:true});w.state.bellWitness={version:1,evidence:['soot','plate'],preparation:'shelter',heardHesper:true,metWitness:true,completed:false,tracking:false};validateBellArc(w.state);assert.deepEqual(bellBattleContext(w),{bellPreparation:'shelter'});assert.equal(w.state.bellWitness.preparation,'shelter');assert.equal(w.state.bellWitness.works.tested,false);});
test('post-guardian shelter and witness routes persist, offer different services, and grant their supply only once',()=>{for(const choice of [0,1]){const t=prepare(choice),w=t.w;w.state.bosses.push(4);w.state.chapter=5;settleBellArc(w);const use=()=>{t.use(bellArcObjects(w).find(o=>o.bellArc==='diverter'));};use();t.dialog.choices[0].action();t.close();const after=choice===0?'shelter-open':'witness-route';assert.equal(w.state.bellWitness.aftercare,after);const items={...w.state.items};use();t.dialog.choices[0].action();t.close();assert.deepEqual(w.state.items,items);w.restore(w.save());t.close();assert.equal(w.state.bellWitness.aftercare,after);use();const action=t.dialog.choices.find(c=>c.label.startsWith(choice===0?'Rest in':'Walk the witness'));assert.ok(action);action.action();t.close();if(choice===1)assert.equal(w.state.scene,212);else assert.equal(w.activeHeroes[0].hp,w.activeHeroes[0].maxHp);}});
test('bell work rejects invented steps and aftercare before the guardian while accepting old partial saves',()=>{const base={version:1,evidence:[],preparation:null};validateBellArc({bellWitness:base});for(const extra of [{works:{inletClosed:false,drainClear:true,returnFreed:false,tested:false}},{testStep:2},{works:{inletClosed:true,drainClear:true,returnFreed:true,tested:true},aftercare:'shelter-open',completed:false}])assert.throws(()=>validateBellArc({bellWitness:{...base,...extra}}),/bell return/);});
test('returning after the guardian guides to the unfinished aftermath even after chapter five begins',()=>{const t=prepare(1),w=t.w;w.state.bosses.push(4);w.state.chapter=5;settleBellArc(w);w.state.scene=292;assert.equal(bellArcObjective(w).object.to,'bell_crypt');w.state.scene=125;assert.equal(bellArcObjective(w).object.bellArc,'diverter');t.use(bellArcObjects(w).find(o=>o.bellArc==='diverter'));t.dialog.choices[0].action();t.close();assert.equal(bellArcObjective(w),null);w.state.scene=212;assert.equal(bellArcObjective(w),null);});
